head.script:
scwin.onpageload = function () {
};

// 읽기 전용 상태 확인 : getReadOnly() 와 내부 입력창 readOnly
scwin.btn_check_onclick = function (e) {
    let inputEl = document.getElementById(spn_a.id + "___input");
    scwin.setReturnValue("getReadOnly() : " + spn_a.getReadOnly() + " / 입력창 readOnly : " + (inputEl ? inputEl.readOnly : "없음") + " / 값 : " + spn_a.getValue());
};

scwin.spn_a_onviewchange = function (info) {
    scwin.setReturnValue("onviewchange : " + info.oldValue + " → " + info.newValue);
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
